  const questions = useSignal<any[]>([]);
  const currentQuestion = useSignal(0);
  const answers = useSignal<Record<string, string>>({});
  const timeLeft = useSignal(0);
  const { cameraEnabled, capturePhoto } = useCamera(attempt);
  const loading = useSignal(true);
  const submitting = useSignal(false);
  const cheatCount = useSignal(0);
  const showWarning = useSignal(false);
  const warningMessage = useSignal("");

  // ÔöÇÔöÇ Initialize exam ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  useVisibleTask$(async () => {
    if (!isAuthenticated()) {
      await nav("/");
      return;
    }
    user.value = getUserData();

    try {
      // Request camera permission handled by useCamera

      // Start attempt
      const data = await attemptsApi.start(examId, cameraEnabled.value);
      attempt.value = data.attempt;
      questions.value = data.attempt.exam?.questions || [];
      timeLeft.value = data.attempt.exam?.duration * 60; // Convert to seconds

      // Connect WebSocket
      const ws = getWsClient();
      ws.connect();
      ws.send("student:join", {
        userId: user.value.id,
        fullName: user.value.fullName,
        attemptId: data.attempt.id,
        examId,
        cameraEnabled: cameraEnabled.value,
      });

      // Handle force-submit from proctor
      ws.on("force:submit", async () => {
        await submitExam();
      });

      // Start timer
      const timer = setInterval(() => {
        timeLeft.value--;
        if (timeLeft.value <= 0) {
          clearInterval(timer);
          submitExam();
        }
      }, 1000);

      // Request fullscreen
      try {
        await document.documentElement.requestFullscreen();
      } catch {
        // Fullscreen may not be available
      }

      loading.value = false;
    } catch (e: any) {
      console.error("Failed to start exam:", e);
    }
  });

  // ÔöÇÔöÇ Cheat Detection: Page Visibility ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  useOnDocument(
    "visibilitychange",
    $(() => {
      if (document.hidden && attempt.value) {
        logCheat("TAB_SWITCH", "Siswa berpindah tab");
      }
    })
  );

  // ÔöÇÔöÇ Cheat Detection: Fullscreen Exit ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  useOnDocument(
    "fullscreenchange",
    $(() => {
      if (!document.fullscreenElement && attempt.value) {
        logCheat("FULLSCREEN_EXIT", "Siswa keluar dari fullscreen");
        // Try to re-enter fullscreen
        try {
          document.documentElement.requestFullscreen();
        } catch {
          // ignore
        }
      }
    })
  );

  // ÔöÇÔöÇ Log cheat event ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  const logCheat = $(async (type: string, description: string) => {
    cheatCount.value++;
    showWarning.value = true;
    warningMessage.value = `ÔÜá´©Å Peringatan: ${description}. Pelanggaran ke-${cheatCount.value}`;

    // Auto-hide after 3 seconds
    setTimeout(() => {
      showWarning.value = false;
    }, 3000);

    // Log to server
    try {
      await cheatLogsApi.log({
        attemptId: attempt.value.id,
        cheatType: type,
        description,
      });

      // Notify via WebSocket
      const ws = getWsClient();
      ws.send("cheat:detected", {
        cheatType: type,
        description,
      });

      // Capture photo if camera is enabled
      capturePhoto(type, description);
    } catch {
      // silently fail
    }
  });

  // ÔöÇÔöÇ Save answer ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  const saveAnswer = $(async (questionId: string, optionId: string) => {
    answers.value = { ...answers.value, [questionId]: optionId };

    try {
      await attemptsApi.answer(attempt.value.id, { questionId, optionId });
    } catch {
      // silently fail
    }
  });

  // ÔöÇÔöÇ Submit exam ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  const submitExam = $(async () => {
    if (submitting.value) return;
    submitting.value = true;

    try {
      const ws = getWsClient();
      ws.send("student:submit", {});

      const result = await attemptsApi.submit(attempt.value.id);

      // Exit fullscreen
      if (document.fullscreenElement) {
        await document.exitFullscreen();
      }

      ws.disconnect();

      // Show result then redirect
      alert(`Ujian selesai!\nNilai: ${Math.round(result.result.score)}\nStatus: ${result.result.passed ? 'LULUS Ô£ô' : 'BELUM LULUS Ô£ù'}`);
      await nav("/student/");
    } catch (e: any) {
      submitting.value = false;
      alert("Gagal mengirim ujian: " + e.message);
    }
  });

  // ÔöÇÔöÇ Format timer ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m.toString().padStart(2, "0")}:${s.toString().padStart(2, "0")}`;
  };

  return (
    <div class="min-h-screen bg-surface-900 select-none" onContextMenu$={(e) => e.preventDefault()}>
      {/* Cheat Warning Overlay */}
      {showWarning.value && (
        <div class="fixed inset-0 z-50 flex items-center justify-center bg-danger/10 backdrop-blur-sm animate-fade-in">
          <div class="bg-surface-800 border-2 border-danger rounded-2xl p-8 max-w-md text-center animate-shake shadow-2xl shadow-danger/20">
            <div class="w-16 h-16 mx-auto mb-4 rounded-full bg-danger/10 flex items-center justify-center">
              <svg class="w-8 h-8 text-danger" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2">
                <path stroke-linecap="round" stroke-linejoin="round" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
              </svg>
            </div>
            <p class="text-danger font-bold text-lg mb-2">Pelanggaran Terdeteksi!</p>
            <p class="text-surface-300 text-sm">{warningMessage.value}</p>
          </div>
        </div>
      )}

      {loading.value ? (
        <div class="flex items-center justify-center h-screen">
          <div class="text-center">
            <div class="w-12 h-12 border-2 border-primary-500 border-t-transparent rounded-full animate-spin mx-auto mb-4" />
            <p class="text-surface-400">Memuat ujian...</p>
          </div>
        </div>
      ) : (
        <div class="flex flex-col h-screen">
          {/* Top Bar */}
          <div class="glass border-b border-surface-700/50 px-4 py-3 flex items-center justify-between shrink-0">
            <div class="flex items-center gap-4">
              <h1 class="text-sm font-semibold text-surface-200 truncate max-w-xs">
                {attempt.value?.exam?.title}
              </h1>
              {!cameraEnabled.value && (
                <span class="text-xs px-2 py-0.5 bg-warning/10 text-warning rounded-full border border-warning/20">
                  ­ƒôÀ Kamera OFF
                </span>
              )}
            </div>

            {/* Timer */}
            <div class={`flex items-center gap-2 px-4 py-1.5 rounded-full font-mono text-sm font-bold ${
              timeLeft.value <= 300
                ? 'bg-danger/10 text-danger border border-danger/20 animate-pulse-glow'
                : 'bg-surface-800 text-surface-200 border border-surface-700'
            }`}>
              <svg class="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2">
                <path stroke-linecap="round" stroke-linejoin="round" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
              </svg>
              {formatTime(timeLeft.value)}
            </div>

            <div class="flex items-center gap-3">
              {cheatCount.value > 0 && (
                <span class="text-xs px-2.5 py-1 bg-danger/10 text-danger rounded-full border border-danger/20">
                  ÔÜá {cheatCount.value} pelanggaran
                </span>
              )}
              <span class="text-xs text-surface-500">
                {currentQuestion.value + 1}/{questions.value.length}
              </span>
            </div>
          </div>

          {/* Progress Bar */}
          <div class="h-1 bg-surface-800 shrink-0">
            <div
              class="h-full bg-gradient-to-r from-primary-500 to-info transition-all duration-300"
              style={`width: ${((currentQuestion.value + 1) / questions.value.length) * 100}%`}
            />
          </div>

          {/* Question Content */}
          <div class="flex-1 overflow-auto p-6">
            <div class="max-w-3xl mx-auto animate-fade-in" key={currentQuestion.value}>
              {/* Question Number */}
              <div class="inline-flex items-center gap-2 px-3 py-1.5 rounded-full bg-primary-500/10 text-primary-400 text-sm font-medium border border-primary-500/20 mb-4">
                Soal {currentQuestion.value + 1}
                <span class="text-surface-500">/ {questions.value.length}</span>
              </div>

              {/* Question Text */}
              <h2 class="text-xl font-medium text-surface-100 mb-6 leading-relaxed">
                {questions.value[currentQuestion.value]?.text}
              </h2>

              {/* Options */}
              <div class="space-y-3">
                {questions.value[currentQuestion.value]?.options?.map((option: any, idx: number) => {
                  const isSelected = answers.value[questions.value[currentQuestion.value]?.id] === option.id;
                  const letters = ["A", "B", "C", "D", "E"];

                  return (
                    <button
                      key={option.id}
                      onClick$={() => saveAnswer(questions.value[currentQuestion.value].id, option.id)}
                      class={`w-full p-4 rounded-xl text-left transition-all duration-200 flex items-start gap-3 group ${
                        isSelected
                          ? 'bg-primary-500/10 border-2 border-primary-500 text-surface-100 shadow-lg shadow-primary-500/10'
                          : 'bg-surface-800/50 border border-surface-700/50 text-surface-300 hover:border-surface-500 hover:bg-surface-800'
                      }`}
                    >
                      <span class={`shrink-0 w-8 h-8 rounded-lg flex items-center justify-center text-sm font-bold transition-all ${
                        isSelected
                          ? 'bg-primary-500 text-white'
                          : 'bg-surface-700 text-surface-400 group-hover:bg-surface-600'
                      }`}>
                        {letters[idx]}
                      </span>
                      <span class="pt-1">{option.text}</span>
                    </button>
                  );
                })}
              </div>
            </div>
          </div>

          {/* Navigation Footer */}
          <div class="glass border-t border-surface-700/50 px-6 py-4 flex items-center justify-between shrink-0">
            {/* Question dots */}
            <div class="flex items-center gap-1.5 flex-wrap max-w-md">
              {questions.value.map((_: any, idx: number) => (
                <button
                  key={idx}
                  onClick$={() => { currentQuestion.value = idx; }}
                  class={`w-7 h-7 rounded-lg text-xs font-medium transition-all ${
                    idx === currentQuestion.value
                      ? 'bg-primary-500 text-white scale-110'
                      : answers.value[questions.value[idx]?.id]
                        ? 'bg-success/20 text-success border border-success/30'
                        : 'bg-surface-800 text-surface-400 hover:bg-surface-700'
                  }`}
                >
                  {idx + 1}
                </button>
              ))}
            </div>

            {/* Nav buttons */}
            <div class="flex items-center gap-3">
              {currentQuestion.value > 0 && (
                <button
                  onClick$={() => { currentQuestion.value--; }}
                  class="px-4 py-2 rounded-xl bg-surface-800 text-surface-300 hover:bg-surface-700 transition-colors text-sm"
                >
                  ÔåÉ Sebelumnya
                </button>
              )}

              {currentQuestion.value === questions.value.length - 1 ? (
                <button
                  onClick$={submitExam}
                  disabled={submitting.value}
                  class="px-6 py-2 rounded-xl bg-success text-white font-medium hover:bg-success/90 transition-colors text-sm shadow-lg shadow-success/20 disabled:opacity-50"
                >
                  {submitting.value ? "Mengirim..." : "Selesai & Kirim"}
                </button>
              ) : (
                <button
                  onClick$={() => { currentQuestion.value++; }}
                  class="px-4 py-2 rounded-xl bg-gradient-primary text-white font-medium hover:scale-[1.02] active:scale-[0.98] transition-all text-sm shadow-lg shadow-primary-500/20"
                >
                  Selanjutnya ÔåÆ
                </button>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
});

export const head: DocumentHead = {
  title: "Ujian ÔÇö Examinator",
};

import { component$, useSignal, useVisibleTask$ } from "@builder.io/qwik";
import type { DocumentHead } from "@builder.io/qwik-city";
import { useNavigate } from "@builder.io/qwik-city";
import { examsApi, attemptsApi } from "~/lib/api";
import { getUserData, isAuthenticated, logout } from "~/lib/auth";
import { Clock } from "~/components/ui/clock";
import { Greeting } from "~/components/ui/greeting";

// ÔöÇÔöÇÔöÇ Student Dashboard ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

export default component$(() => {
  const user = useSignal<any>(null);
  const exams = useSignal<any[]>([]);
  const attempts = useSignal<any[]>([]);
  const loading = useSignal(true);
  const nav = useNavigate();
  const activeTab = useSignal<"available" | "history">("available");
  const searchQuery = useSignal("");

  useVisibleTask$(async () => {
    if (!isAuthenticated()) {
      await nav("/");
      return;
    }
    user.value = getUserData();

    try {
      const [examData, attemptData] = await Promise.all([
        examsApi.list(),
        attemptsApi.my(),
      ]);
      exams.value = examData.exams || [];
      attempts.value = attemptData.attempts || [];
    } catch {
      // handle error silently
    } finally {
      loading.value = false;
    }
  });

  const getAttemptForExam = (examId: string) => {
    return attempts.value.find((a: any) => a.examId === examId);
  };

  const availableExams = exams.value.filter(exam => {
    const attempt = getAttemptForExam(exam.id);
    return !attempt || (attempt.status !== "SUBMITTED" && attempt.status !== "TIMED_OUT");
  });

  const historyExams = exams.value.filter(exam => {
    const attempt = getAttemptForExam(exam.id);
    return attempt && (attempt.status === "SUBMITTED" || attempt.status === "TIMED_OUT");
  });

  const filteredHistory = historyExams.filter(exam => 
    exam.title.toLowerCase().includes(searchQuery.value.toLowerCase()) ||
    exam.subject.toLowerCase().includes(searchQuery.value.toLowerCase())
  );

  return (
    <div class="min-h-screen bg-surface-900 bg-gradient-mesh">
      {/* Header */}
      <header class="glass sticky top-0 z-40">
        <div class="max-w-7xl mx-auto px-4 sm:px-6 py-4 flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div class="flex items-center justify-between">
            <div class="flex items-center gap-3">
              <div class="w-8 h-8 rounded-lg bg-gradient-primary flex items-center justify-center shadow-md shadow-primary-500/20">
                <svg class="w-4 h-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2">
                  <path stroke-linecap="round" stroke-linejoin="round" d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
                </svg>
              </div>
              <span class="font-bold text-gradient text-lg tracking-tight">Examinator</span>
            </div>
            
            <div class="md:hidden">
              <Clock />
            </div>
          </div>
          
          <div class="flex items-center justify-between md:justify-end gap-6">
            <div class="hidden md:block">
              <Clock />
            </div>
            
            <div class="flex items-center gap-4 border-l border-surface-200 pl-4">
              <div class="flex items-center gap-3 cursor-pointer group" onClick$={() => nav('/profile/')}>
                <div class="w-9 h-9 rounded-full bg-gradient-to-tr from-primary-400 to-secondary-500 flex items-center justify-center text-white ring-2 ring-white shadow-sm transition-transform group-hover:scale-105">
                  <span class="text-sm font-bold">{user.value?.fullName?.charAt(0) || "U"}</span>
                </div>
                <div class="hidden sm:block text-left">
                  <div class="text-sm text-surface-800 font-semibold leading-tight">{user.value?.fullName}</div>
                  <div class="text-xs text-surface-500 leading-tight capitalize">{user.value?.role.toLowerCase()}</div>
                </div>
              </div>
              
              <button
                onClick$={() => { logout(); }}
                class="p-2 rounded-lg text-surface-500 hover:text-danger hover:bg-danger/10 transition-colors"
                title="Keluar"
              >
                <svg class="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2">
                  <path stroke-linecap="round" stroke-linejoin="round" d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" />
                </svg>
              </button>
            </div>
          </div>
        </div>
      </header>

      {/* Content */}
      <main class="max-w-7xl mx-auto px-4 sm:px-6 py-8">
        {/* Welcome Section */}
        <div class="mb-10 animate-fade-in flex flex-col sm:flex-row items-center justify-between bg-white rounded-2xl p-6 shadow-sm border border-surface-200">
          <div class="text-center sm:text-left">
            <h1 class="text-2xl font-bold text-surface-800 mb-1">
              <Greeting name={user.value?.fullName} />
            </h1>
            <p class="text-surface-500">
              {user.value?.kelas && <span class="text-primary-600 font-medium bg-primary-50 px-2 py-0.5 rounded-md text-xs mr-2">{user.value.kelas}</span>}
              Lihat dan mulai ujian yang tersedia
            </p>
          </div>
        </div>

        {/* Tabs */}
        <div class="flex items-center gap-2 mb-8 border-b border-surface-200">
          <button
            onClick$={() => activeTab.value = "available"}
            class={`px-4 py-2 text-sm font-medium border-b-2 transition-colors ${
              activeTab.value === "available"
                ? "border-primary-500 text-primary-600"
                : "border-transparent text-surface-500 hover:text-surface-700 hover:border-surface-300"
            }`}
          >
            Ujian Tersedia ({availableExams.length})
          </button>
          <button
            onClick$={() => activeTab.value = "history"}
            class={`px-4 py-2 text-sm font-medium border-b-2 transition-colors ${
              activeTab.value === "history"
                ? "border-primary-500 text-primary-600"
                : "border-transparent text-surface-500 hover:text-surface-700 hover:border-surface-300"
            }`}
          >
            Riwayat Ujian ({historyExams.length})
          </button>
        </div>

        {/* Loading */}
        {loading.value && (
          <div class="flex items-center justify-center py-20">
            <div class="w-8 h-8 border-2 border-primary-500 border-t-transparent rounded-full animate-spin" />
          </div>
        )}

        {/* Available Exams */}
        {!loading.value && activeTab.value === "available" && (
          <>
            {availableExams.length === 0 ? (
              <div class="text-center py-20 bg-white rounded-2xl border border-surface-200 shadow-sm">
                <div class="w-16 h-16 mx-auto mb-4 rounded-full bg-surface-100 flex items-center justify-center text-3xl">
                  ­ƒôØ
                </div>
                <h3 class="text-lg font-bold text-surface-800 mb-1">Tidak ada ujian</h3>
                <p class="text-surface-500 text-sm">Belum ada ujian yang tersedia untuk Anda saat ini.</p>
              </div>
            ) : (
              <div class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {availableExams.map((exam: any, idx: number) => {
                  const attempt = getAttemptForExam(exam.id);
                  const isInProgress = attempt?.status === "IN_PROGRESS";

                  return (
                    <div
                      key={exam.id}
                      class="bg-white rounded-2xl p-6 shadow-sm border border-surface-200 hover:shadow-md hover:border-primary-300 transition-all duration-300 animate-fade-in flex flex-col"
                      style={`animation-delay: ${idx * 50}ms`}
                    >
                      <div class="flex items-center justify-between mb-4">
                        <span class="text-xs font-bold tracking-wider px-3 py-1 rounded-full bg-primary-50 text-primary-700 border border-primary-100 uppercase">
                          {exam.subject}
                        </span>
                        {isInProgress && (
                          <span class="text-xs font-bold px-3 py-1 rounded-full bg-warning/10 text-warning-700 border border-warning/20 flex items-center gap-1.5">
                            <span class="w-1.5 h-1.5 rounded-full bg-warning-500 animate-pulse"></span>
                            Sedang Berjalan
                          </span>
                        )}
                      </div>

                      <h3 class="text-xl font-bold text-surface-900 mb-2 line-clamp-2">{exam.title}</h3>
                      {exam.description && <p class="text-sm text-surface-500 mb-6 line-clamp-2 flex-grow">{exam.description}</p>}

                      <div class="flex items-center justify-between text-sm text-surface-600 bg-surface-50 p-3 rounded-xl border border-surface-100 mb-6">
                        <div class="flex flex-col">
                          <span class="text-xs text-surface-400 mb-0.5">Durasi</span>
                          <span class="font-semibold">{exam.duration} mnt</span>
                        </div>
                        <div class="w-px h-8 bg-surface-200"></div>
                        <div class="flex flex-col">
                          <span class="text-xs text-surface-400 mb-0.5">Soal</span>
                          <span class="font-semibold">{exam._count?.questions || 0}</span>
                        </div>
                        <div class="w-px h-8 bg-surface-200"></div>
                        <div class="flex flex-col">
                          <span class="text-xs text-surface-400 mb-0.5">KKM</span>
                          <span class="font-semibold text-primary-600">{exam.passingScore}</span>
                        </div>
                      </div>

                      <button
                        onClick$={async () => await nav(`/student/exam/${exam.id}/`)}
                        class={`w-full py-3 rounded-xl font-bold text-sm transition-all duration-200 shadow-sm ${
                          isInProgress
                            ? 'bg-warning-50 text-warning-700 border border-warning-300 hover:bg-warning-100'
                            : 'bg-primary-600 text-white hover:bg-primary-700 active:scale-[0.98]'
                        }`}
                      >
                        {isInProgress ? "Lanjutkan Mengerjakan" : "Mulai Mengerjakan"}
                      </button>
                    </div>
                  );
                })}
              </div>
            )}
          </>
        )}

        {/* History / Datatable */}
        {!loading.value && activeTab.value === "history" && (
          <div class="animate-fade-in bg-white rounded-2xl shadow-sm border border-surface-200 overflow-hidden">
            <div class="p-6 border-b border-surface-200 flex flex-col sm:flex-row sm:items-center justify-between gap-4">
              <h2 class="text-lg font-bold text-surface-800">Riwayat Ujian</h2>
              <div class="relative w-full sm:w-64">
                <div class="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <svg class="h-4 w-4 text-surface-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                  </svg>
                </div>
                <input
                  type="text"
                  placeholder="Cari ujian..."
                  class="block w-full pl-10 pr-3 py-2 border border-surface-300 rounded-lg leading-5 bg-white placeholder-surface-400 focus:outline-none focus:ring-2 focus:ring-primary-500 focus:border-primary-500 sm:text-sm transition-all"
                  value={searchQuery.value}
                  onInput$={(e) => searchQuery.value = (e.target as HTMLInputElement).value}
                />
              </div>
            </div>

            <div class="overflow-x-auto">
              <table class="min-w-full divide-y divide-surface-200">
                <thead class="bg-surface-50">
                  <tr>
                    <th scope="col" class="px-6 py-3 text-left text-xs font-semibold text-surface-500 uppercase tracking-wider">Mata Pelajaran</th>
                    <th scope="col" class="px-6 py-3 text-left text-xs font-semibold text-surface-500 uppercase tracking-wider">Judul Ujian</th>
                    <th scope="col" class="px-6 py-3 text-center text-xs font-semibold text-surface-500 uppercase tracking-wider">KKM</th>
                    <th scope="col" class="px-6 py-3 text-center text-xs font-semibold text-surface-500 uppercase tracking-wider">Nilai</th>
                    <th scope="col" class="px-6 py-3 text-center text-xs font-semibold text-surface-500 uppercase tracking-wider">Status</th>
                  </tr>
                </thead>
                <tbody class="bg-white divide-y divide-surface-200 text-sm">
                  {filteredHistory.length === 0 ? (
                    <tr>
                      <td colSpan={5} class="px-6 py-8 text-center text-surface-500">
                        {searchQuery.value ? "Tidak ada riwayat ujian yang cocok dengan pencarian." : "Belum ada riwayat ujian yang diselesaikan."}
                      </td>
                    </tr>
                  ) : (
                    filteredHistory.map((exam) => {
                      const attempt = getAttemptForExam(exam.id);
                      const isPassed = attempt?.score !== null && attempt?.score >= exam.passingScore;
                      
                      return (
                        <tr key={exam.id} class="hover:bg-surface-50 transition-colors">
                          <td class="px-6 py-4 whitespace-nowrap">
                            <span class="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-primary-100 text-primary-800">
                              {exam.subject}
                            </span>
                          </td>
                          <td class="px-6 py-4 whitespace-nowrap font-medium text-surface-900">
                            {exam.title}
                          </td>
                          <td class="px-6 py-4 whitespace-nowrap text-center text-surface-500">
                            {exam.passingScore}
                          </td>
                          <td class="px-6 py-4 whitespace-nowrap text-center">
                            <span class={`font-bold ${isPassed ? 'text-success' : 'text-danger'}`}>
                              {attempt?.score !== null ? Math.round(attempt.score) : '-'}
                            </span>
                          </td>
                          <td class="px-6 py-4 whitespace-nowrap text-center">
                            {isPassed ? (
                              <span class="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-md text-xs font-medium bg-green-100 text-green-800 border border-green-200">
                                <svg class="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2"><path stroke-linecap="round" stroke-linejoin="round" d="M5 13l4 4L19 7" /></svg>
                                Lulus
                              </span>
                            ) : (
                              <span class="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-md text-xs font-medium bg-red-100 text-red-800 border border-red-200">
                                <svg class="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2"><path stroke-linecap="round" stroke-linejoin="round" d="M6 18L18 6M6 6l12 12" /></svg>
                                Remidi
                              </span>
                            )}
                          </td>
                        </tr>
                      );
                    })
                  )}
                </tbody>
              </table>
            </div>
            {/* Pagination Placeholder (Mock for UI purpose, full integration depends on backend paginating or client side slicing) */}
            {filteredHistory.length > 0 && (
              <div class="px-6 py-3 border-t border-surface-200 flex items-center justify-between bg-surface-50">
                <span class="text-sm text-surface-500">Menampilkan <span class="font-medium text-surface-900">{filteredHistory.length}</span> riwayat</span>
              </div>
            )}
          </div>
        )}
      </main>
    </div>
  );
});

export const head: DocumentHead = {
  title: "Dashboard Siswa ÔÇö Examinator",
};
